import type {
  Residence,
  ResidenceDetailContent,
  ResidenceGridContent,
  ResidencePhoto,
  ResidenceStatus,
} from "@cinematic/section-library";

/**
 * The eighteen Aurelia residences. Facts are authored once here; the listing
 * (`/residences`) and the detail pages (`/residences/[slug]`) both read them.
 *
 * Photography is licensed Unsplash placeholder material. The key plans and
 * floor plans are drawings generated by `scripts/build-residence-plans.mjs`
 * from this same inventory, so they are never cropped to fill a frame.
 */

function shot(id: string, room: string, alt: string, caption: string): ResidencePhoto {
  return {
    id,
    src: `https://images.unsplash.com/${id}?auto=format&fit=crop&w=1800&q=80`,
    alt,
    caption,
    room,
  };
}

