function build(spec: UnitSpec): Residence {
  const type = TYPES[spec.type];
  if (!type) {
    throw new Error(`Unknown residence type: ${spec.type}`);
  }

  return {
    slug: spec.number,
    number: spec.number,
    name: `No. ${spec.number}`,
    type: spec.type,
    typeLabel: type.label,
    block: spec.block,
    floor: spec.floor,
    floorLabel: FLOOR_LABELS[spec.floor] ?? `Floor ${spec.floor}`,
    bedrooms: spec.bedrooms,
    bathrooms: type.bathrooms,
    interiorSqm: spec.interiorSqm,
    outdoorSqm: spec.outdoorSqm,
    outdoorLabel: type.outdoorLabel,
    orientation: spec.orientation,
    status: spec.status,
    completion: spec.completion,
    description: spec.description,
    features: type.features,
    schematic: {
      src: `/residences/key-${spec.number}.svg`,
      alt: `Key plan: ${type.label} No. ${spec.number} marked on the ${
        FLOOR_LABELS[spec.floor] ?? `floor ${spec.floor}`
      } of the ${spec.block} block.`,
      caption: `Key plan — where No. ${spec.number} sits on its floor.`,
    },
    plan: {
      src: `/residences/plan-${spec.number}.svg`,
      alt: `Floor plan: No. ${spec.number}, ${spec.bedrooms} bedrooms, ${spec.interiorSqm} m² inside and ${spec.outdoorSqm} m² of ${type.outdoorLabel.toLowerCase()}.`,
      caption: `Floor plan — No. ${spec.number}, ${spec.interiorSqm} m².`,
    },
    photos: spec.photos.map((key) => PHOTOS[key]),
  };
}

export const residences: Residence[] = UNITS.map(build);

